package com.bank.budgetreview;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class HighestSpendDemo {
    private static final Logger log = Logger.getLogger("BudgetReview");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT", 1000000),
            new Employee("Amit", "IT", 600000),
            new Employee("Priya", "Sales", 900000));  // IT total 1.6M > Sales 900k
        BudgetReviewService service = new BudgetReviewService();

        log.info(() -> "Highest total spend dept: "
            + service.deptWithHighestSpend(staff).orElse("none"));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final double salary;
    Employee(String name, String department, double salary) {
        this.name = name; this.department = department; this.salary = salary;
    }
    String getDepartment() { return department; }
    double getSalaryAsDouble() { return salary; }
}

// ─── Would be in service/BudgetReviewService.java ───
class BudgetReviewService {
    Optional<String> deptWithHighestSpend(List<Employee> staff) {
        Map<String, Double> totalByDept = staff.stream()
            .filter(e -> e.getDepartment() != null)
            .collect(groupingBy(Employee::getDepartment,
                summingDouble(Employee::getSalaryAsDouble)));     // TOTAL per dept
        return totalByDept.entrySet().stream()
            .max(Map.Entry.<String, Double>comparingByValue()
                .thenComparing(Map.Entry.comparingByKey()))
            .map(Map.Entry::getKey);
    }
}
